1	package tui
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	
8		"github.com/charmbracelet/bubbles/list"
9		"github.com/charmbracelet/bubbles/spinner"
10		"github.com/charmbracelet/bubbles/textinput"
11		tea "github.com/charmbracelet/bubbletea"
12	
13		"github.com/immuta/operations/apps/birdseye/internal/registry"
14		"github.com/immuta/operations/services/crow/pkg/api"
15		"github.com/immuta/operations/services/crow/pkg/client"
16	)
17	
18	// PickerState is the explicit state machine the picker walks.
19	type PickerState int
20	
21	const (
22		StateAskModule PickerState = iota
23		StateAskVersionA
24		StateAskVersionB
25		StateLoading
26		StateBrowser
27		StateError
28	)
29	
30	// Deps groups the picker's external dependencies. nil is acceptable for
31	// unit tests of the picker's input/state machinery (those tests never
32	// reach StateLoading).
33	type Deps struct {
34		Client *client.Client
35		Reg    *registry.Registry
36	}
37	
38	type versionsLoadedMsg struct {
39		versions []string
40		err      error
41	}
42	
43	type pairLoadedMsg struct {
44		a, b []byte
45		err  error
46	}
47	
48	// versionItem implements bubbles/list.Item for a single version string.
49	type versionItem string
50	
51	func (v versionItem) FilterValue() string { return string(v) }
52	func (v versionItem) Title() string       { return string(v) }
53	func (v versionItem) Description() string { return "" }
54	
55	// Picker is a single bubbletea Model whose internal state enum drives
56	// which sub-widget is rendered.
57	type Picker struct {
58		ctx        context.Context
59		deps       *Deps
60		state      PickerState
61		input      textinput.Model
62		moduleID   api.ModuleIdentifier
63		versionsA  list.Model
64		versionsB  list.Model
65		chosenA    string
66		chosenB    string
67		spinner    spinner.Model
68		width      int
69		height     int
70		errMessage string
71		pairA      []byte
72		pairB      []byte
73	}
74	
75	// NewPicker constructs a picker. deps may be nil for input-only tests
76	// (no network dispatch occurs in that case).
77	func NewPicker(ctx context.Context, deps *Deps) *Picker {
78		ti := textinput.New()
79		ti.Placeholder = "namespace/name/provider"
80		ti.Focus()
81		sp := spinner.New()
82		sp.Spinner = spinner.Dot
83		return &Picker{
84			ctx:     ctx,
85			deps:    deps,
86			state:   StateAskModule,
87			input:   ti,
88			spinner: sp,
89		}
90	}
91	
92	func (p *Picker) State() PickerState { return p.state }
93	func (p *Picker) HasError() bool     { return p.errMessage != "" }
94	
95	// Bytes returns the fetched tarballs once StateBrowser is reached, so
96	// the cmd integration can extract + diff and build the browser.
97	func (p *Picker) Bytes() ([]byte, []byte) { return p.pairA, p.pairB }
98	
99	func (p *Picker) Init() tea.Cmd { return textinput.Blink }
100	
101	func (p *Picker) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
102		switch msg := msg.(type) {
103		case tea.WindowSizeMsg:
104			p.width, p.height = msg.Width, msg.Height
105			return p, nil
106		case tea.KeyMsg:
107			if msg.Type == tea.KeyCtrlC ||
108				(msg.Type == tea.KeyRunes && string(msg.Runes) == "q" && p.state != StateAskModule) {
109				return p, tea.Quit
110			}
111		}
112		switch p.state {
113		case StateAskModule:
114			return p.updateAskModule(msg)
115		case StateAskVersionA:
116			return p.updateAskVersionA(msg)
117		case StateAskVersionB:
118			return p.updateAskVersionB(msg)
119		case StateLoading:
120			return p.updateLoading(msg)
121		}
122		return p, nil
123	}
124	
125	func (p *Picker) updateAskModule(msg tea.Msg) (tea.Model, tea.Cmd) {
126		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
127			id, err := parseModuleAddressForPicker(p.input.Value())
128			if err != nil {
129				p.errMessage = err.Error()
130				return p, nil
131			}
132			p.errMessage = ""
133			p.moduleID = id
134			if p.deps == nil || p.deps.Client == nil {
135				// Test harness path: do not dispatch network cmd.
136				return p, nil
137			}
138			p.state = StateLoading
139			return p, p.loadVersionsCmd(id)
140		}
141		var cmd tea.Cmd
142		p.input, cmd = p.input.Update(msg)
143		return p, cmd
144	}
145	
146	func (p *Picker) loadVersionsCmd(id api.ModuleIdentifier) tea.Cmd {
147		return func() tea.Msg {
148			versions, err := p.deps.Client.ListVersions(p.ctx, id)
149			return versionsLoadedMsg{versions: versions, err: err}
150		}
151	}
152	
153	func (p *Picker) updateLoading(msg tea.Msg) (tea.Model, tea.Cmd) {
154		switch m := msg.(type) {
155		case versionsLoadedMsg:
156			if m.err != nil {
157				p.errMessage = m.err.Error()
158				p.state = StateError
159				return p, nil
160			}
161			items := make([]list.Item, 0, len(m.versions))
162			for _, v := range m.versions {
163				items = append(items, versionItem(v))
164			}
165			p.versionsA = list.New(items, list.NewDefaultDelegate(), p.width, p.height-4)
166			p.versionsA.Title = "Select version A"
167			p.state = StateAskVersionA
168			return p, nil
169		case pairLoadedMsg:
170			if m.err != nil {
171				p.errMessage = m.err.Error()
172				p.state = StateError
173				return p, nil
174			}
175			p.pairA = m.a
176			p.pairB = m.b
177			// Stay in StateLoading until SetBrowser is called by the cmd
178			// integration. To make the bubbletea program quit (so the cmd
179			// code can run the second-stage Run), return tea.Quit here. The
180			// cmd integration will inspect Bytes() and either run the
181			// browser or report an error.
182			return p, tea.Quit
183		}
184		var cmd tea.Cmd
185		p.spinner, cmd = p.spinner.Update(msg)
186		return p, cmd
187	}
188	
189	func (p *Picker) updateAskVersionA(msg tea.Msg) (tea.Model, tea.Cmd) {
190		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
191			item, ok := p.versionsA.SelectedItem().(versionItem)
192			if !ok {
193				return p, nil
194			}
195			p.chosenA = string(item)
196			items := make([]list.Item, 0, len(p.versionsA.Items()))
197			for _, it := range p.versionsA.Items() {
198				if v := it.(versionItem); string(v) != p.chosenA {
199					items = append(items, v)
200				}
201			}
202			p.versionsB = list.New(items, list.NewDefaultDelegate(), p.width, p.height-4)
203			p.versionsB.Title = "Select version B"
204			p.state = StateAskVersionB
205			return p, nil
206		}
207		var cmd tea.Cmd
208		p.versionsA, cmd = p.versionsA.Update(msg)
209		return p, cmd
210	}
211	
212	func (p *Picker) updateAskVersionB(msg tea.Msg) (tea.Model, tea.Cmd) {
213		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
214			item, ok := p.versionsB.SelectedItem().(versionItem)
215			if !ok {
216				return p, nil
217			}
218			p.chosenB = string(item)
219			if p.deps == nil || p.deps.Reg == nil {
220				return p, nil
221			}
222			p.state = StateLoading
223			return p, p.loadPairCmd(p.moduleID, p.chosenA, p.chosenB)
224		}
225		var cmd tea.Cmd
226		p.versionsB, cmd = p.versionsB.Update(msg)
227		return p, cmd
228	}
229	
230	func (p *Picker) loadPairCmd(id api.ModuleIdentifier, va, vb string) tea.Cmd {
231		return func() tea.Msg {
232			a, b, err := p.deps.Reg.FetchPair(p.ctx,
233				api.Module{ModuleIdentifier: id, Version: va},
234				api.Module{ModuleIdentifier: id, Version: vb})
235			return pairLoadedMsg{a: a, b: b, err: err}
236		}
237	}
238	
239	func (p *Picker) View() string {
240		switch p.state {
241		case StateAskModule:
242			errBlock := ""
243			if p.errMessage != "" {
244				errBlock = "\nerror: " + p.errMessage
245			}
246			return "module address (namespace/name/provider):\n" + p.input.View() + errBlock
247		case StateLoading:
248			return p.spinner.View() + " loading…"
249		case StateAskVersionA:
250			return p.versionsA.View()
251		case StateAskVersionB:
252			return p.versionsB.View()
253		case StateError:
254			return "error: " + p.errMessage + "\npress q to quit"
255		}
256		return ""
257	}
258	
259	// parseModuleAddressForPicker mirrors cmd.parseModuleAddress without
260	// the import cycle. Returns a typed error for inline display in the TUI.
261	func parseModuleAddressForPicker(s string) (api.ModuleIdentifier, error) {
262		parts := strings.Split(s, "/")
263		if len(parts) != 3 {
264			return api.ModuleIdentifier{}, fmt.Errorf("module address must be namespace/name/provider, got %q", s)
265		}
266		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
267		if err := id.Validate(); err != nil {
268			return api.ModuleIdentifier{}, err
269		}
270		return id, nil
271	}
