17	func TestPickerAdvancesOnEnter(t *testing.T) {
18		p := NewPicker(context.Background(), nil)
19		for _, r := range "iac/comply/aws" {
20			_, _ = p.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
21		}
22		_, cmd := p.Update(tea.KeyMsg{Type: tea.KeyEnter})
23		// nil deps means no network cmd is dispatched, but state has advanced
24		// past validation. (See test in next assertion.)
25		_ = cmd
26		if p.HasError() {
27			t.Errorf("did not expect error for valid module; got: %v", p)
28		}
29	}
