31	func TestPickerRejectsBadAddressInline(t *testing.T) {
32		p := NewPicker(context.Background(), nil)
33		for _, r := range "garbage" {
34			_, _ = p.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
35		}
36		_, cmd := p.Update(tea.KeyMsg{Type: tea.KeyEnter})
37		if cmd != nil {
38			t.Error("did not expect a tea.Cmd for invalid address")
39		}
40		if !p.HasError() {
41			t.Error("expected inline error on invalid address")
42		}
43	}
