	"testing"

	tea "github.com/charmbracelet/bubbletea"
)

func TestPickerStartsAtAskModule(t *testing.T) {
	p := NewPicker(context.Background(), nil, nil, "")
	if p.State() != StateAskModule {
		t.Errorf("initial state = %v, want StateAskModule", p.State())
	}
}

func TestPickerAdvancesOnEnter(t *testing.T) {
	p := NewPicker(context.Background(), nil, nil, "")
	for _, r := range "iac/comply/aws" {
		_, _ = p.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
	}
	_, cmd := p.Update(tea.KeyMsg{Type: tea.KeyEnter})
