	}
	_, cmd := p.Update(tea.KeyMsg{Type: tea.KeyEnter})
	if cmd != nil {
		t.Error("did not expect a tea.Cmd for invalid address")
	}
	if !p.HasError() {
		t.Error("expected inline error on invalid address")
	}
}

